begin;create extension if not exists pgtap with schema extensions;select plan(26);
insert into auth.users(instance_id,id,aud,role,email,encrypted_password,email_confirmed_at,created_at,updated_at)values('00000000-0000-0000-0000-000000000000','99800000-0000-4000-8000-000000000001','authenticated','authenticated','template-owner@example.test','',now(),now(),now());set local role authenticated;select set_config('request.jwt.claim.sub','99800000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99800000-0000-4000-8000-000000000001","role":"authenticated"}',true);select public.create_business('template-test','Template Test','Template Test','sole_proprietorship','retail','{"city":"Manila"}');select set_config('test.template_org',(select id::text from public.organizations where slug='template-test'),true);select set_config('test.template_id',(select id::text from public.business_os_templates where key='retail-store-os'),true);select set_config('test.template_v1',(select id::text from public.business_os_template_versions where template_id=current_setting('test.template_id')::uuid and version=1),true);
reset role;insert into public.subscriptions(organization_id,provider,plan_key,status)values(current_setting('test.template_org')::uuid,'internal','growth','trialing');set local role authenticated;select set_config('request.jwt.claim.sub','99800000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99800000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select results_eq($$select count(*)from public.business_os_templates$$,$$select 3::bigint$$,'Registry exposes published Business OS templates');select results_eq($$select count(*)from public.business_os_template_versions where status='published'$$,$$select 5::bigint$$,'Registry versions are separate published snapshots');select is(jsonb_typeof((select definition from public.business_os_template_versions where id=current_setting('test.template_v1')::uuid)),'object','Published definition is a declarative metadata snapshot');
select lives_ok($$select public.install_business_os_template(current_setting('test.template_org')::uuid,current_setting('test.template_v1')::uuid)$$,'Retail Business OS installs atomically');select results_eq($$select template_id,installed_version_id,status from public.business_os_installations where organization_id=current_setting('test.template_org')::uuid$$,$$select current_setting('test.template_id')::uuid,current_setting('test.template_v1')::uuid,'active'::text$$,'Installation records template and exact version');select results_eq($$select count(*)from public.organization_modules where organization_id=current_setting('test.template_org')::uuid and is_enabled$$,$$select 5::bigint$$,'Template enables its module selection');select results_eq($$select count(*)from public.organization_modules where organization_id=current_setting('test.template_org')::uuid and source_template_id=current_setting('test.template_id')::uuid$$,$$select 5::bigint$$,'Installed modules retain template provenance');select results_eq($$select singular_label,plural_label,status from public.object_definitions where organization_id=current_setting('test.template_org')::uuid and key='supplier_contact'$$,$$select 'Supplier Contact'::text,'Supplier Contacts'::text,'active'::text$$,'Template object is cloned into tenant metadata');select results_eq($$select count(*)from public.field_definitions where organization_id=current_setting('test.template_org')::uuid$$,$$select 2::bigint$$,'Custom fields are cloned');select results_eq($$select count(*)from public.form_definitions definition join public.form_layouts layout on layout.form_definition_id=definition.id where definition.organization_id=current_setting('test.template_org')::uuid$$,$$select 1::bigint$$,'Forms and layouts are tenant-specific');select results_eq($$select view_type,scope from public.view_definitions where organization_id=current_setting('test.template_org')::uuid$$,$$select 'table'::text,'shared'::text$$,'Views are cloned as shared tenant metadata');select results_eq($$select count(*)from public.report_definitions where organization_id=current_setting('test.template_org')::uuid$$,$$select 1::bigint$$,'Reports are cloned');select results_eq($$select count(*)from public.dashboard_definitions where organization_id=current_setting('test.template_org')::uuid$$,$$select 1::bigint$$,'Dashboards are cloned');select results_eq($$select locale,date_format,week_starts_on from public.business_settings where organization_id=current_setting('test.template_org')::uuid$$,$$select 'en-PH'::text,'MM/dd/yyyy'::text,1::smallint$$,'Default settings are applied on first installation');select results_eq($$select terminology->>'inventory'from public.business_os_installations where organization_id=current_setting('test.template_org')::uuid$$,$$select 'Stock'::text$$,'Terminology is copied into the installation overlay');select results_eq($$select count(*)from public.business_os_installation_events where organization_id=current_setting('test.template_org')::uuid and event='installed'$$,$$select 1::bigint$$,'Initial installation is audited');select lives_ok($$select public.install_business_os_template(current_setting('test.template_org')::uuid,current_setting('test.template_v1')::uuid)$$,'Installing the current version is idempotent');select results_eq($$select count(*)from public.business_os_installation_events where organization_id=current_setting('test.template_org')::uuid$$,$$select 1::bigint$$,'Idempotent replay creates no duplicate installation event');
reset role;update public.object_definitions set singular_label='Vendor Contact'where organization_id=current_setting('test.template_org')::uuid and key='supplier_contact';select throws_ok($$update public.business_os_template_versions set change_summary='Mutated'where id=current_setting('test.template_v1')::uuid$$,'P0001','Published Business OS versions are immutable.','Published source version cannot be modified');insert into public.business_os_template_versions(template_id,version,definition,change_summary,status,published_at)select template_id,3,jsonb_set(definition,'{objects,0,fields}',(definition#>'{objects,0,fields}')||'[{"key":"email","label":"Email","dataType":"text","required":false,"unique":false,"sortOrder":2,"config":{}}]'::jsonb),'Add supplier email','published',now()from public.business_os_template_versions where id=current_setting('test.template_v1')::uuid;select set_config('test.template_v2',(select id::text from public.business_os_template_versions where template_id=current_setting('test.template_id')::uuid and version=3),true);set local role authenticated;select set_config('request.jwt.claim.sub','99800000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"99800000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.install_business_os_template(current_setting('test.template_org')::uuid,current_setting('test.template_v2')::uuid)$$,'Newer version installs additively');select results_eq($$select singular_label from public.object_definitions where organization_id=current_setting('test.template_org')::uuid and key='supplier_contact'$$,$$select 'Vendor Contact'::text$$,'Template update preserves customized object terminology');select results_eq($$select count(*)from public.field_definitions where organization_id=current_setting('test.template_org')::uuid and key='email'$$,$$select 1::bigint$$,'Template update adds new missing resources');select results_eq($$select installed_version_id from public.business_os_installations where organization_id=current_setting('test.template_org')::uuid$$,$$select current_setting('test.template_v2')::uuid$$,'Installation advances to exact new version');select ok((select preserved_count>0 and created_count=1 from public.business_os_installation_events where organization_id=current_setting('test.template_org')::uuid and event='updated'),'Update audit distinguishes preserved customizations and new resources');select throws_ok($$select public.install_business_os_template(current_setting('test.template_org')::uuid,(select version.id from public.business_os_template_versions version join public.business_os_templates template on template.id=version.template_id where template.key='service-business-os'order by version.version desc limit 1))$$,'P0001','This Business already has a different Business OS installed.','A tenant cannot accidentally overlay a different Business OS');select throws_ok($$insert into public.business_os_installations(organization_id,template_id,installed_version_id,installed_by)values(current_setting('test.template_org')::uuid,current_setting('test.template_id')::uuid,current_setting('test.template_v2')::uuid,auth.uid())$$,'42501','permission denied for table business_os_installations','Clients cannot bypass the installation RPC');select *from finish();rollback;
